using System.Text;

namespace Implock;

internal static class Emitter
{
    public const string AttributeSource = """
        // <auto-generated/>
        #nullable enable
        namespace Implock
        {
            /// <summary>Marks a bodiless partial method whose body is stored in implement.lock.</summary>
            [global::System.AttributeUsage(global::System.AttributeTargets.Method, AllowMultiple = false, Inherited = false)]
            internal sealed class ImplementAttribute : global::System.Attribute
            {
                /// <summary>Named tests as "name: expression" strings; they are part of the spec.</summary>
                public ImplementAttribute(params string[] tests)
                {
                    Tests = tests;
                }

                public string[] Tests { get; }
            }
        }
        """;

    public static string Render(MethodSpec spec, string body)
    {
        var sb = new StringBuilder();
        sb.Append("// <auto-generated>\n// Emitted from implement.lock by Implock. Change the spec and run 'implock generate' instead of editing this.\n// </auto-generated>\n");
        sb.Append(spec.NullableEnabled ? "#nullable enable\n" : "#nullable disable\n");
        foreach (var directive in spec.Usings)
        {
            sb.Append(directive).Append('\n');
        }

        var indent = 0;
        if (spec.Namespace.Length > 0)
        {
            sb.Append("namespace ").Append(spec.Namespace).Append("\n{\n");
            indent = 1;
        }

        foreach (var header in spec.TypeHeaders)
        {
            Indent(sb, indent).Append(header).Append('\n');
            Indent(sb, indent).Append("{\n");
            indent++;
        }

        Indent(sb, indent).Append(spec.Declaration).Append('\n');
        Indent(sb, indent).Append("{\n");
        sb.Append(body.Replace("\r\n", "\n")).Append('\n');
        Indent(sb, indent).Append("}\n");

        while (indent > 0)
        {
            indent--;
            Indent(sb, indent).Append("}\n");
        }

        return sb.ToString();
    }

    private static StringBuilder Indent(StringBuilder sb, int level) => sb.Append(' ', level * 4);
}
